1	// Package rollup downsamples a time series into fixed windows aligned to
2	// the Unix epoch, and merges rollups that share a window size.
3	//
4	// A Roller is safe for concurrent use: samples may be filed, windows read,
5	// and rollers merged from multiple goroutines at once. Every read observes
6	// an internally consistent snapshot, and a merge is visible to other
7	// callers either in full or not at all.
8	package rollup
9	
10	import (
11		"errors"
12		"math"
13		"math/bits"
14		"sync"
15		"sync/atomic"
16		"time"
17	)
18	
19	// ErrOutOfOrder is returned by Add when a sample predates the most recent
20	// sample the roller has already accepted.
21	var ErrOutOfOrder = errors.New("rollup: out of order")
22	
23	// ErrWindowMismatch is returned by Merge when the two rollers use different
24	// window sizes.
25	var ErrWindowMismatch = errors.New("rollup: window mismatch")
26	
27	// Window holds the aggregate statistics of the samples filed into one
28	// window. Start is the window's left-closed, right-open lower bound.
29	type Window struct {
30		Start time.Time
31		Count int64
32		Sum   float64
33		Min   float64
34		Max   float64
35	}
36	
37	// Roller aggregates samples into fixed windows of a single size.
38	//
39	// The zero value is not usable; build one with New. All methods are safe
40	// to call concurrently from multiple goroutines.
41	type Roller struct {
42		// mu guards buckets, latest, and hasAny. window and id are fixed at
43		// construction and read without the lock.
44		//
45		// buckets is one flat slice kept sorted by window start: samples
46		// arrive in non-decreasing time order, so Add appends in amortized
47		// constant time, Windows reads out without re-sorting, and Merge is
48		// a single linear pass over both sides.
49		mu      sync.RWMutex
50		id      uint64
51		window  time.Duration
52		buckets []Window
53		latest  time.Time
54		hasAny  bool
55	}
56	
57	// idGen hands out unique roller IDs so Merge can lock two rollers in a
58	// consistent order and concurrent cross-merges cannot deadlock.
59	var idGen atomic.Uint64
60	
61	// New builds a roller with the given window size. It panics with
62	// "rollup: bad window" if window is not positive.
63	func New(window time.Duration) *Roller {
64		if window <= 0 {
65			panic("rollup: bad window")
66		}
67		return &Roller{
68			id:     idGen.Add(1),
69			window: window,
70		}
71	}
72	
73	// startOf returns the start of the window containing at, aligned to an
74	// integer multiple of the window size since the Unix epoch. The arithmetic
75	// is exact for any time value, including ones whose nanosecond offset from
76	// the epoch does not fit in an int64.
77	func (r *Roller) startOf(at time.Time) time.Time {
78		sec := at.Unix()
79		nsec := int64(at.Nanosecond())
80		w := r.window.Nanoseconds()
81		if sec >= -9223372036 && sec <= 9223372035 {
82			// sec*1e9+nsec fits in an int64. Rounding a negative ns down to
83			// a window multiple can reach ns-(w-1), so stay on the fast
84			// path only when that product cannot overflow either.
85			if ns := sec*1e9 + nsec; ns >= math.MinInt64+w-1 {
86				start := ns / w
87				if ns%w != 0 && ns < 0 {
88					start--
89				}
90				return time.Unix(0, start*w).UTC()
91			}
92		}
93		return windowStartWide(sec, nsec, w)
94	}
95	
96	// windowStartWide is the 128-bit slow path of startOf, for times whose
97	// nanosecond offset from the epoch overflows an int64.
98	func windowStartWide(sec, nsec, w int64) time.Time {
99		// t = sec*1e9 + nsec as a 128-bit two's-complement value (hi, lo).
100		uhi, ulo := bits.Mul64(uint64(sec), uint64(1e9))
101		if sec < 0 {
102			uhi -= 1e9
103		}
104		hi := int64(uhi)
105		lo := ulo + uint64(nsec)
106		if lo < ulo {
107			hi++
108		}
109		// Round t down to a multiple of w: start = t - floorMod(t, w).
110		rem := floorMod128(hi, lo, w)
111		if lo < rem {
112			hi--
113		}
114		lo -= rem
115		// Split start into whole seconds and nanoseconds.
116		ns := floorMod128(hi, lo, 1e9)
117		if lo < ns {
118			hi--
119		}
120		lo -= ns
121		return time.Unix(quo128(hi, lo, 1e9), int64(ns)).UTC()
122	}
123	
124	// floorMod128 returns t mod y for the signed 128-bit value t = (hi<<64)|lo
125	// and positive y, with the result in [0, y).
126	func floorMod128(hi int64, lo uint64, y int64) uint64 {
127		yu := uint64(y)
128		if hi >= 0 {
129			return rem128(uint64(hi), lo, yu)
130		}
131		// Negate the 128-bit value, take the remainder, and reflect it back
132		// into [0, y) for floored (not truncated) division.
133		mlo := -lo
134		mhi := -uint64(hi)
135		if lo != 0 {
136			mhi--
137		}
138		if r := rem128(mhi, mlo, yu); r != 0 {
139			return yu - r
140		}
141		return 0
142	}
143	
144	// quo128 returns (hi<<64|lo)/y for a signed 128-bit dividend known to be an
145	// exact multiple of y, with a quotient that fits in an int64.
146	func quo128(hi int64, lo uint64, y int64) int64 {
147		yu := uint64(y)
148		if hi >= 0 {
149			q, _ := bits.Div64(uint64(hi), lo, yu)
150			return int64(q)
151		}
152		mlo := -lo
153		mhi := -uint64(hi)
154		if lo != 0 {
155			mhi--
156		}
157		q, _ := bits.Div64(mhi, mlo, yu)
158		return -int64(q)
159	}
160	
161	// rem128 returns (hi<<64 | lo) mod y for unsigned hi, lo and y > 0.
162	func rem128(hi, lo, y uint64) uint64 {
163		if hi >= y {
164			hi %= y
165		}
166		return bits.Rem64(hi, lo, y)
167	}
168	
169	// find locates the bucket starting at start. The second result reports
170	// whether it exists; when it does not, the index is where it would be
171	// inserted to keep buckets sorted.
172	func (r *Roller) find(start time.Time) (int, bool) {
173		sec, nsec := start.Unix(), int64(start.Nanosecond())
174		lo, hi := 0, len(r.buckets)
175		for lo < hi {
176			mid := int(uint(lo+hi) >> 1)
177			s := r.buckets[mid].Start
178			if ss, sn := s.Unix(), int64(s.Nanosecond()); ss < sec || (ss == sec && sn < nsec) {
179				lo = mid + 1
180			} else {
181				hi = mid
182			}
183		}
184		if lo < len(r.buckets) {
185			if s := r.buckets[lo].Start; s.Unix() == sec && int64(s.Nanosecond()) == nsec {
186				return lo, true
187			}
188		}
189		return lo, false
190	}
191	
192	// addTo folds one sample into w. Count saturates at math.MaxInt64 instead
193	// of overflowing; Sum, Min, and Max keep updating afterwards.
194	func addTo(w *Window, value float64) {
195		if w.Count < math.MaxInt64 {
196			w.Count++
197		}
198		w.Sum += value
199		if value < w.Min {
200			w.Min = value
201		}
202		if value > w.Max {
203			w.Max = value
204		}
205	}
206	
207	// Add files a sample into its window. A sample earlier than the most recent
208	// accepted sample is rejected with ErrOutOfOrder and leaves the roller
209	// unchanged; a sample at the same instant is accepted and counted again.
210	//
211	// Concurrent Adds are serialized: each takes effect in the order it
212	// acquires the roller, and the out-of-order check is measured against the
213	// samples accepted before it in that order.
214	func (r *Roller) Add(at time.Time, value float64) error {
215		r.mu.Lock()
216		defer r.mu.Unlock()
217		if r.hasAny && at.Before(r.latest) {
218			return ErrOutOfOrder
219		}
220		start := r.startOf(at)
221		n := len(r.buckets)
222		switch {
223		case n == 0:
224			r.buckets = append(r.buckets, newBucket(start, value))
225		case !start.Before(r.buckets[n-1].Start):
226			// The common case: the sample lands in the newest window or
227			// just past it, so the sorted order is maintained for free.
228			if r.buckets[n-1].Start.Equal(start) {
229				addTo(&r.buckets[n-1], value)
230			} else {
231				r.buckets = append(r.buckets, newBucket(start, value))
232			}
233		default:
234			// The sample belongs to an older window, which can only happen
235			// after a merge brought in windows past latest.
236			if i, ok := r.find(start); ok {
237				addTo(&r.buckets[i], value)
238			} else {
239				r.buckets = append(r.buckets, Window{})
240				copy(r.buckets[i+1:], r.buckets[i:])
241				r.buckets[i] = newBucket(start, value)
242			}
243		}
244		r.latest = at
245		r.hasAny = true
246		return nil
247	}
248	
249	// newBucket returns a window holding a single sample.
250	func newBucket(start time.Time, value float64) Window {
251		return Window{Start: start, Count: 1, Sum: value, Min: value, Max: value}
252	}
253	
254	// Window returns the bucket whose start matches start exactly. The second
255	// result is false when no bucket starts at that instant; no nearby bucket
256	// is substituted. The returned Window is a copy and stays valid no matter
257	// what is filed afterwards.
258	func (r *Roller) Window(start time.Time) (Window, bool) {
259		r.mu.RLock()
260		defer r.mu.RUnlock()
261		if i, ok := r.find(start); ok {
262			return r.buckets[i], true
263		}
264		return Window{}, false
265	}
266	
267	// Windows returns all buckets in time order. An empty roller yields an
268	// empty slice. The result is a snapshot of one moment: samples filed after
269	// the call do not alter it.
270	func (r *Roller) Windows() []Window {
271		r.mu.RLock()
272		defer r.mu.RUnlock()
273		out := make([]Window, len(r.buckets))
274		copy(out, r.buckets)
275		return out
276	}
277	
278	// Merge folds other's buckets into this roller: counts and sums add,
279	// minimums take the smaller, maximums take the larger, and buckets only one
280	// side has are carried over as-is. Merging does not affect out-of-order
281	// tracking. It panics with "rollup: nil roller" if other is nil, and
282	// returns ErrWindowMismatch, leaving this roller unchanged, if the window
283	// sizes differ.
284	//
285	// The merge is atomic with respect to every other call on either roller:
286	// concurrent readers see this roller wholly before or wholly after the
287	// merge, and a sample filed into other while the merge runs is either
288	// folded in completely or not at all. If the two rollers merge each other
289	// at the same time, the outcome matches some serial order of the two
290	// merges; neither is lost.
291	func (r *Roller) Merge(other *Roller) error {
292		if other == nil {
293			panic("rollup: nil roller")
294		}
295		if other.window != r.window {
296			return ErrWindowMismatch
297		}
298		if r == other {
299			r.mu.Lock()
300			defer r.mu.Unlock()
301			for i := range r.buckets {
302				w := &r.buckets[i]
303				w.Count = satAdd(w.Count, w.Count)
304				w.Sum += w.Sum
305			}
306			return nil
307		}
308		// Lock both rollers in ID order so simultaneous merges in
309		// opposite directions cannot deadlock.
310		first, second := r, other
311		if other.id < r.id {
312			first, second = other, r
313		}
314		first.mu.Lock()
315		second.mu.Lock()
316		defer second.mu.Unlock()
317		defer first.mu.Unlock()
318	
319		switch {
320		case len(other.buckets) == 0:
321			return nil
322		case len(r.buckets) == 0:
323			r.buckets = append(r.buckets, other.buckets...)
324			return nil
325		}
326		// Both sides are sorted by window start, so the merge is one linear
327		// pass and one backing array, no per-bucket copies or lookups.
328		merged := make([]Window, 0, len(r.buckets)+len(other.buckets))
329		i, j := 0, 0
330		for i < len(r.buckets) && j < len(other.buckets) {
331			a, b := &r.buckets[i], &other.buckets[j]
332			switch {
333			case a.Start.Before(b.Start):
334				merged = append(merged, *a)
335				i++
336			case b.Start.Before(a.Start):
337				merged = append(merged, *b)
338				j++
339			default:
340				w := *a
341				w.Count = satAdd(w.Count, b.Count)
342				w.Sum += b.Sum
343				if b.Min < w.Min {
344					w.Min = b.Min
345				}
346				if b.Max > w.Max {
347					w.Max = b.Max
348				}
349				merged = append(merged, w)
350				i++
351				j++
352			}
353		}
354		merged = append(merged, r.buckets[i:]...)
355		merged = append(merged, other.buckets[j:]...)
356		r.buckets = merged
357		return nil
358	}
359	
360	// satAdd returns a + b saturated at math.MaxInt64 instead of overflowing.
361	func satAdd(a, b int64) int64 {
362		if b > math.MaxInt64-a {
363			return math.MaxInt64
364		}
365		return a + b
366	}
