10	// wantStart computes the epoch-aligned window start for at with 128-bit
11	// big-integer arithmetic, as an independent oracle for startOf.
12	func wantStart(at time.Time, w time.Duration) time.Time {
13		ns := big.NewInt(at.Unix())
14		ns.Mul(ns, big.NewInt(1e9))
15		ns.Add(ns, big.NewInt(int64(at.Nanosecond())))
16		wns := big.NewInt(w.Nanoseconds())
17		q := new(big.Int).Quo(ns, wns)
18		if new(big.Int).Rem(ns, wns).Sign() != 0 && ns.Sign() < 0 {
19			q.Sub(q, big.NewInt(1))
20		}
21		start := q.Mul(q, wns)
22		sec := new(big.Int).Quo(start, big.NewInt(1e9))
23		rem := new(big.Int).Rem(start, big.NewInt(1e9))
24		if rem.Sign() != 0 && start.Sign() < 0 {
25			sec.Sub(sec, big.NewInt(1))
26			rem.Add(rem, big.NewInt(1e9))
27		}
28		return time.Unix(sec.Int64(), rem.Int64()).UTC()
29	}
