        switch c := compareStart(a[i].Start, b[j].Start); {
        case c < 0:
            merged = append(merged, a[i]); i++
        case c > 0:
            merged = append(merged, b[j]); j++
        default:
            w := a[i]
            w.Count = satAdd(w.Count, b[j].Count)
            w.Sum += b[j].Sum
            if b[j].Min < w.Min { w.Min = b[j].Min }
            if b[j].Max > w.Max { w.Max = b[j].Max }
